contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint lockTime, uint putAmount, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (putAmount)); require(putAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= putAmount);
        c.Put{value: putAmount}(lockTime); if (__ESBMC_reverted()) return;
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        require(beforeUnlock < block.timestamp);
        require(beforeBalance >= c.MinSum());
        require(beforeBalance >= collectAmount);
        uint balanceBefore = address(this).balance;
        c.Collect(collectAmount); if (__ESBMC_reverted()) return;
        uint balanceAfter = address(this).balance;
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        assert(afterBalance == beforeBalance - collectAmount && balanceAfter == balanceBefore + collectAmount);
    }

    receive() external payable {}
}

