pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 lockTime, uint256 putAmount, uint256 collectAmount) internal {
        putAmount = bound(putAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= putAmount);
        try c.Put{value: putAmount}(lockTime) {} catch { return; }
        uint256 beforeUnlock;
        uint256 beforeBalance;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { beforeUnlock = __r0; beforeBalance = __r1; } catch { return; }
        vm.assume(beforeUnlock < block.timestamp);
        vm.assume(beforeBalance >= c.MinSum());
        vm.assume(beforeBalance >= collectAmount);
        uint balanceBefore = address(this).balance;
        try c.Collect(collectAmount) {} catch { return; }
        uint balanceAfter = address(this).balance;
        uint256 afterUnlock;
        uint256 afterBalance;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { afterUnlock = __r0; afterBalance = __r1; } catch { return; }
        assertTrue(afterBalance == beforeBalance - collectAmount && balanceAfter == balanceBefore + collectAmount);
    }

    function testFuzz_run(uint256 lockTime, uint256 putAmount, uint256 collectAmount) public {
        _run(lockTime, putAmount, collectAmount);
    }

    receive() external payable {}
}
